package simulation
import("time";"context")
type ActionExecutor func(action Action,character SimCharacter)ActionResult
type EventSink func(eventType,actorID,targetID string,payload map[string]any)
type Runner struct{Population *Service;State *StateService;BuildContext ContextBuilder;Execute ActionExecutor;Emit EventSink;Persistence PersistenceSink}
func(r *Runner)Tick(now time.Time)int{if r.Population==nil||r.State==nil||r.BuildContext==nil||r.Execute==nil{return 0};count:=0;for _,c:=range r.Population.List(1000){if !c.Active{continue};if r.Persistence!=nil{_=r.Persistence.EnsureCharacter(context.Background(),c)};ctx:=r.BuildContext(c.ID);state:=r.State.Get(c.ID);result:=DecideAndValidateWithState(c,ctx,state);if r.Persistence!=nil{_=r.Persistence.RecordAction(context.Background(),c.ID,result.Action,result.Accepted)};if !result.Accepted{r.State.Tick(c.ID);continue};if !r.State.CanAffordAction(c.ID,result.Action.Type){r.State.Tick(c.ID);continue};result=r.Execute(result.Action,c);if result.Accepted{_,_=r.State.ApplyEconomy(c.ID,result.Action.Type);r.State.Apply(c.ID,result.Action.Type,now);if result.Action.Type==ActionSocialize&&result.Action.TargetID!=""{rel:=state.Relationships[result.Action.TargetID];rel.FromID=c.ID;rel.ToID=result.Action.TargetID;rel.Kind=RelationshipAcquaintance;rel.Familiarity=clamp(rel.Familiarity+5);rel.Trust=clampSigned(rel.Trust+2);rel.Affinity=clampSigned(rel.Affinity+4);rel.Interactions++;rel.LastInteraction=&now;r.State.RecordRelationship(c.ID,rel,now);if rp,ok:=r.Persistence.(RelationshipPersistence);ok{_=rp.RecordRelationship(context.Background(),rel)};if rep,ok:=r.Persistence.(ReputationPersistence);ok{_=rep.PropagateSocialReputation(context.Background(),c.ID,1,2,"positive social interaction")};if r.Emit!=nil{r.Emit("SIMULATION_RELATIONSHIP_CHANGED",c.ID,rel.ToID,map[string]any{"affinity":rel.Affinity,"trust":rel.Trust,"familiarity":rel.Familiarity,"interactions":rel.Interactions})}};r.State.Tick(c.ID);if r.Persistence!=nil{st:=r.State.Get(c.ID);if len(st.Memories)>0{_=r.Persistence.RecordMemory(context.Background(),c.ID,st.Memories[len(st.Memories)-1])};if ep,ok:=r.Persistence.(EconomyPersistence);ok{_=ep.RecordEconomy(context.Background(),c.ID,r.State.Get(c.ID).Economy)}};if r.Emit!=nil{st:=r.State.Get(c.ID);r.Emit("SIMULATED_ACTION",c.ID,result.Action.TargetID,map[string]any{"action":string(result.Action.Type),"mood":st.Mood,"balance":st.Economy.Balance})};count++}};return count}
